/* V8.06 navigation and discovery. No persistence/schema changes. */
const V8E={epoch:0,tradeRequest:0,journalReturn:null};
function v8RouteElement(route){return $( {live:'liveView',session:'v8SessionView',after:'v8AfterView',reviews:'v8ReviewsView',htflearning:'v8HtfReviewView'}[route]||route+'View');}
function v8FocusHeading(root){const h=root?.querySelector('h2,h3');if(!h)return;h.tabIndex=-1;h.focus({preventScroll:true});}
const ergonomicView=showView;
showView=function(view){const previous=V8.route;if(view!==previous){V8E.epoch++;if(view!=='journal'){journalOpenSeq++;detailRequestSeq++;}if(view==='journal'&&!(previous==='settings'&&V8.settingsReturn==='journal'&&V8E.journalReturn))V8E.journalReturn={route:previous,owner:currentUser?.id,y:window.scrollY,focus:document.activeElement};}ergonomicView(view);if(view!==previous){const root=v8RouteElement(V8.route);root?.scrollIntoView({block:'start',behavior:'instant'});v8FocusHeading(root);}v8SyncBack();};
const ergonomicBackSync=v8SyncBack;
v8SyncBack=function(){ergonomicBackSync();if(V8.route==='htflearning'){v8BackBar.hidden=false;v8BackButton.textContent='← Zurück zur Nachbereitung';document.body.classList.add('v8-has-back');}if(V8.route!=='journal')return;v8BackBar.hidden=false;document.body.classList.add('v8-has-back');const route=V8E.journalReturn?.route;v8BackButton.textContent=route==='playbook'?'← Zurück zum Playbook':route==='reviews'?'← Zurück zu offenen Reviews':route==='analytics'?'← Zurück zur Auswertung':route==='training'?'← Zurück zum Training':'← Zurück zu Start';};
const ergonomicGoBack=v8GoBack;
v8GoBack=function(){if(V8.route!=='journal'){ergonomicGoBack();return;}const context=V8E.journalReturn;const valid=context?.owner===currentUser?.id;const target=valid&&context.route!=='journal'?context.route:'live';draftFlush();showView(target);if(valid){window.scrollTo({top:context.y,behavior:'instant'});if(context.focus?.isConnected&&!context.focus.closest('.hidden,[hidden]'))context.focus.focus({preventScroll:true});}};
const ergonomicMount=mountTradePanes;
mountTradePanes=function(...args){ergonomicMount(...args);const close=$('closeTradeDetails');if(close)close.hidden=true;v8SyncBack();};
// Cancellation is checked after each asynchronous boundary before choosing a destination.
v8OpenTrade=async function(){if(!sessionReady()){showSessionHub();return;}const request=++V8E.tradeRequest,epoch=V8E.epoch,owner=currentUser?.id,session=currentSession?.id;const button=nav.querySelector('[data-v8-nav=trade]');button.setAttribute('aria-busy','true');try{await loadSessionTrades();if(request!==V8E.tradeRequest||epoch!==V8E.epoch||owner!==currentUser?.id||session!==currentSession?.id)return;const open=sessionTrades.filter(t=>!t.exit_at);if(open.length===1){journalScope='current';await openJournalTradeById(open[0].id);}else if(open.length){journalScope='current';showView('journal');$('sessionTrades').classList.remove('hidden');$('sessionTradeList').classList.remove('hidden');$('tradeDetails').classList.add('hidden');}else goToTradeEntry();}catch(e){if(epoch===V8E.epoch&&owner===currentUser?.id)ttToast('Trades nicht geladen: '+e.message,true);}finally{if(request===V8E.tradeRequest)button.removeAttribute('aria-busy');}};
v8OpenReviews=async function(){showView('reviews');await loadOpenReviews();};
// One prominent next action on Start; session management appears after preparation.
$('v8SessionManage').hidden=!sessionReady();const ergonomicHome=v8RefreshHome;
v8RefreshHome=function(){ergonomicHome();$('v8SessionManage').hidden=!sessionReady();};
const hero=$('liveView').querySelector('.v8-hero');hero.querySelector('h2').textContent='Dein nächster Schritt';hero.querySelector('p').textContent='Vorbereiten · Handeln · Lernen';
// Search indexes only explicit setup metadata, never incidental counts/button labels.
const bookToolbar=document.createElement('div');bookToolbar.className='v8-book-toolbar';
const bookLabel=document.createElement('label');bookLabel.textContent='Setup oder Regel suchen';const bookSearch=document.createElement('input');bookSearch.id='v8BookSearch';bookSearch.type='search';bookSearch.placeholder='Name, Trigger, Zone …';bookLabel.append(bookSearch);
const examplesLabel=document.createElement('label');examplesLabel.className='account-pick';const onlyExamples=document.createElement('input');onlyExamples.id='v8BookExamples';onlyExamples.type='checkbox';examplesLabel.append(onlyExamples,document.createTextNode('Nur mit Lernbeispielen'));
const bookCount=document.createElement('p');bookCount.id='v8BookCount';bookCount.setAttribute('role','status');bookCount.setAttribute('aria-live','polite');const clearBook=v8Button('Filter zurücksetzen',()=>{bookSearch.value='';onlyExamples.checked=false;v8FilterBook();bookSearch.focus();},'ghost');bookToolbar.append(bookLabel,examplesLabel,clearBook,bookCount);$('playbookLexicon').before(bookToolbar);
function v8FilterBook(){const normalize=s=>s.normalize('NFKC').toLocaleLowerCase('de');const words=normalize(bookSearch.value.trim()).split(/\s+/).filter(Boolean);const boxes=[...$('playbookLexicon').querySelectorAll(':scope > .book-entry')];let count=0;for(const box of boxes){const hasExamples=Number(box.dataset.examples||0)>0||!!box.querySelector('.v8-htf-example');const metadata=box.dataset.search||box.querySelector(':scope > summary')?.textContent||'';const matches=words.every(w=>normalize(metadata).includes(w))&&(!onlyExamples.checked||hasExamples);box.hidden=!matches;if(matches)count++;}bookCount.textContent=boxes.length?(count+' von '+boxes.length+' Setups'+(count===0?' · Filter anpassen.':'')):'Noch keine Setups geladen.';clearBook.hidden=!words.length&&!onlyExamples.checked;}
bookSearch.addEventListener('input',v8FilterBook);onlyExamples.addEventListener('change',v8FilterBook);
const ergonomicBook=renderBook;let bookRenderSeq=0;
renderBook=async function(...args){const seq=++bookRenderSeq,owner=currentUser?.id;bookToolbar.setAttribute('aria-busy','true');try{await ergonomicBook(...args);if(seq===bookRenderSeq&&owner===currentUser?.id)v8FilterBook();}finally{if(seq===bookRenderSeq)bookToolbar.removeAttribute('aria-busy');}};
const ergonomicReset=resetPrivateState;
resetPrivateState=function(){V8E.epoch++;V8E.tradeRequest++;V8E.journalReturn=null;bookRenderSeq++;bookLoadSeq++;bookSearch.value='';onlyExamples.checked=false;bookCount.textContent='';nav.querySelector('[data-v8-nav=trade]').removeAttribute('aria-busy');ergonomicReset();};
// Arrow/Home/End follows the tab pattern; changing tabs does not submit any form.
$('tradeDetails').addEventListener('keydown',event=>{const button=event.target.closest('[data-pane-button]');if(!button||!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;const buttons=[...$('tradeDetails').querySelectorAll('[data-pane-button]')];let index=buttons.indexOf(button);index=event.key==='Home'?0:event.key==='End'?buttons.length-1:(index+(event.key==='ArrowRight'?1:-1)+buttons.length)%buttons.length;event.preventDefault();buttons[index].click();buttons[index].focus({preventScroll:true});});
const ergonomicOpenJournal=openJournalTradeById;
openJournalTradeById=async function(...args){if(V8.route==='journal'&&$('tradeDetails').classList.contains('hidden'))V8E.journalReturn={route:'journal',list:true,parent:V8E.journalReturn,owner:currentUser?.id,y:window.scrollY,focus:document.activeElement};await ergonomicOpenJournal(...args);if(V8.route==='journal')v8SyncBack();};
const ergonomicJournalBack=v8GoBack;
v8GoBack=function(){const context=V8E.journalReturn;if(V8.route==='journal'&&context?.list&&context.owner===currentUser?.id){$('closeTradeDetails')?.onclick?.();V8E.journalReturn=context.parent;window.scrollTo({top:context.y,behavior:'instant'});context.focus?.focus?.({preventScroll:true});v8SyncBack();return;}ergonomicJournalBack();};
const ergonomicListBack=v8SyncBack;
v8SyncBack=function(){ergonomicListBack();if(V8.route==='journal'&&V8E.journalReturn?.list)v8BackButton.textContent='← Zurück zur Trade-Liste';};
const ergonomicSelectPane=selectTradePane;
selectTradePane=function(key,...args){ergonomicSelectPane(key,...args);$('tradeDetails').querySelectorAll('[data-pane-button]').forEach(button=>button.tabIndex=button.dataset.paneButton===key?0:-1);};

const sessionTradesShortcut=$('v8SessionManage').nextElementSibling;
sessionTradesShortcut.textContent='Trades ansehen';sessionTradesShortcut.hidden=!currentSession;
const compactHome=v8RefreshHome;v8RefreshHome=function(){compactHome();sessionTradesShortcut.hidden=!currentSession;};
v8OpenSessionTrades=async function(){const epoch=V8E.epoch,owner=currentUser?.id,session=currentSession?.id;try{journalScope='current';await loadSessionTrades();if(epoch!==V8E.epoch||owner!==currentUser?.id||session!==currentSession?.id)return;showView('journal');$('sessionTrades').classList.remove('hidden');$('sessionTradeList').classList.remove('hidden');$('tradeDetails').classList.add('hidden');setJournalHeading('Trades der Handelssession');v8SyncFinish();await refreshSessionFinishChecklist();}catch(e){if(epoch===V8E.epoch&&owner===currentUser?.id)ttToast('Handelssession nicht geladen: '+e.message,true);}};
